solution:
function solve(x, y) {
  const t = Array.from({ length: x.length + 1 }, () =>
    Array(y.length + 1).fill(0),
  )
  for (let i = 1; i <= x.length; i++) {
    for (let j = 1; j <= y.length; j++) {
      if (x[i - 1] === y[j - 1]) {
        t[i][j] = t[i - 1][j - 1] + 1
      } else {
        t[i][j] = Math.max(t[i - 1][j], t[i][j - 1])
      }
    }
  }
  return t[x.length][y.length]
}
